+		case info.Mode()&fs.ModeSymlink != 0:
+			return false, errors.New("is a symlink")
+		case !info.Mode().IsRegular():
+			return false, errors.New("is not a regular file")
+		case !w.clobber:
+			return false, errAlreadyExists
