+func selectVersion(a *client.ArtifactWithVersions, version int) (string, string, error) {
+	if err := shared.CheckType(a.Artifact); err != nil {
+		return "", "", err
+	}
+	v, err := shared.FindVersion(a, version)
+	if err != nil {
+		return "", "", err
